-- PT112-S4-Q25. Batch 12.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch12$PT112-S4-Q25$batch12$ AND q.stimulus=$batch12$The judgment that an artist is great always rests on assessments of the work the artist has produced. A series of great works is the only indicator of greatness. Therefore, to say that an artist is great is just to summarize the quality of his or her known works, and the artist’s greatness can provide no basis for predicting the quality of the artist’s unknown or future works.$batch12$ AND q.prompt=$batch12$Which one of the following contains questionable reasoning most similar to that in the argument above?$batch12$ AND q.correct_choice=$batch12$A$batch12$) THEN RAISE EXCEPTION 'Question changed: PT112-S4-Q25'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch12$PT112-S4-Q25$batch12$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT112-S4-Q25'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch12$PT112-S4-Q25$batch12$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch12$Conclusion$batch12$, $batch12$Calling an artist great just summarizes the known works and can't predict future works.$batch12$), (1, $batch12$Evidence$batch12$, $batch12$Judging greatness always rests on the work produced. A series of great works is the only indicator of greatness.$batch12$), (2, $batch12$Evaluate$batch12$, $batch12$Recipe: the only way to know X is by observing Y. So saying X just summarizes Y and predicts nothing beyond it.$batch12$), (3, $batch12$Goal$batch12$, $batch12$X is known only through Y, so X means only past Y and predicts nothing.$batch12$)) v(position,label,body) WHERE q.qid=$batch12$PT112-S4-Q25$batch12$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch12$A$batch12$, $batch12$The only way to know someone has a cold is through symptoms. So "has a cold" just means symptoms shown, and predicts no future symptoms. Same recipe.$batch12$), ($batch12$B$batch12$, $batch12$This concludes some people are physiologically different. No "just a summary" claim.$batch12$), ($batch12$C$batch12$, $batch12$This is the popular trap. It also ends in "can't predict," but it gets there from many different viruses. The original gets there from the only evidence being past observations.$batch12$), ($batch12$D$batch12$, $batch12$Unpredictability comes from viruses differing. Different reason.$batch12$), ($batch12$E$batch12$, $batch12$This concludes we can never be certain someone has a cold, not that the label predicts nothing.$batch12$)) v(letter,body) WHERE q.qid=$batch12$PT112-S4-Q25$batch12$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
